		const cfg = settings();
		const client = createClient({
			url: cfg.url,
			RESP: 2,
			disableOfflineQueue: true,
			commandsQueueMaxLength: 1024,
			commandOptions: { timeout: cfg.commandTimeoutMs },
			socket: {
				...(cfg.url.startsWith("rediss:")
					? { tls: true as const, rejectUnauthorized: true }
					: { tls: false as const }),
