				return Object.freeze({ ...lease, ttlMs });
			}),
		releaseLease: (lease: Lease) =>
			operation("releaseLease", async () => {
				const ownership = token(lease),
					physical = key(lease.name, "lease");
				const result = await command((client) =>
					client.eval(releaseScript, {
						keys: [physical],
						arguments: [ownership],
					}),
				);
